  "rn.fed.all": "Tout le classement", "rn.fed.rank": "{r} sur {n}",
  "doc.country.none": "Ozimut n'a pas encore de classement pour ce pays : la méthode et ses mesures présentées ici sont celles de la France, où elle a été mise au point.",
  "doc.country.ES": "<b>En Espagne.</b> La méthode Ozimut est la même qu'en France, avec un réglage mesuré sur les courses espagnoles (juillet 2025 – octobre 2026, mêmes coureurs) : en forêt, la valeur d'un circuit se calcule sur les deux tiers les plus rapides (au lieu de 90 %), ce qui prédit mieux le classement de 0,4 point de duels. L'Espagne n'a pas d'indice officiel d'où partir : la première saison de l'archive part du niveau habituel de chaque catégorie par rapport à H21, tel qu'on le mesure en France, puis les courses font le reste. Tous les coureurs des courses espagnoles sont classés, étrangers compris. Sur les mêmes coureurs, l'indice Ozimut prédit mieux qui finit devant que la règle de la FEDO appliquée le jour même (temps du vainqueur de la catégorie sur celui du coureur, moyenne des 6 meilleures courses de 12 mois) : +5,0 points de duels en forêt, +5,4 en sprint. Le classement de la FEDO est montré tel qu'elle le publie, dans l'onglet « Classement FEDO » du classement. L'étude ci-dessous est celle faite en France.",
  "doc.country.CA": "<b>Au Canada.</b> La méthode Ozimut est la même qu'en France, sans réglage propre. Le Canada n'a pas de classement national d'où partir, et la plupart des courses de club se courent sur des circuits par niveau (« Intermediate », « Advanced ») plutôt que par catégorie d'âge : la première saison de l'archive fait partir chaque coureur du niveau habituel de sa catégorie quand le résultat la donne, sinon d'un niveau commun, et les courses font le reste. Les résultats viennent des clubs : les fichiers d'Orienteering Ottawa (depuis 2023), ceux de Ramblers et ceux de WhyJustRun (Colombie-Britannique, Alberta, provinces maritimes, depuis 2010). Les coureurs sont reconnus à leur seul nom. L'étude ci-dessous est celle faite en France.",
