  "prov.title": "Résultats",
  "prov.lede": "Les résultats des courses récentes tels que les organisateurs les publient — sur liveresultat, WinSplits, Helga ou leur site —, souvent avant la fédération : course par course, avec les temps intermédiaires quand ils sont publiés et, là où Ozimut a les résultats de votre fédération, les scores et indices provisoires.",
