  "prov.ongoingNote.other": "Course en cours : {n} coureurs sont encore en course ou pas encore partis. Ces résultats sont partiels et changeront jusqu'à la fin de la course.",
  "prov.start.hint": "La liste de départ publiée par l'organisateur (liveresultat), avant la course ; CN : ceux d'aujourd'hui dans la discipline de la course ; attendu : la place que l'indice Ozimut donne parmi les coureurs du circuit",
  "prov.start.hintPlain": "La liste de départ publiée par l'organisateur, avant la course",
  "prov.notCn": "hors CN", "prov.noResult": "aucun résultat trouvé", "prov.noSite": "site du club inconnu", "prov.noSite.hint": "Ni l'agenda ni les courses du club ne donnent son site : ses fichiers de résultats ne peuvent pas être cherchés",
  "prov.runs": "Dernière collecte", "prov.dueNow": "courses à voir maintenant", "prov.run.at": "Collecte", "prov.run.looked": "Courses vues / à voir",
  "prov.run.changed": "Nouveautés", "prov.run.requests": "Requêtes", "prov.run.seconds": "Secondes / budget", "prov.run.cut": "budget épuisé",
  "prov.run.failed": "en erreur", "prov.run.of": "courses vues sur", "prov.refusedOnly": "sources fermées aux robots",
  "prov.def": "Seules les courses des 60 derniers jours sont présentées. Sources lues : liveresultat, WinSplits, Helga, Orientation Data et le site de l'organisateur (fichiers de résultats et de temps intermédiaires) ; les sites qui refusent les robots ne sont pas lus. Chaque course est regardée à chaque passage horaire pendant 3 jours, puis chaque jour jusqu'au 14e. Les scores et indices sont provisoires : ceux que la fédération publie ensuite peuvent différer.",
  "prov.generated": "Données du", "prov.notFound": "Course inconnue.", "prov.site": "Site de l'organisateur", "prov.documents": "Documents trouvés",
  "prov.source": "Source", "prov.doc": "Document", "prov.format": "Format", "prov.classes": "Circuits", "prov.found": "Trouvé", "prov.changed": "Modifié",
  "prov.noDoc": "Rien trouvé pour l'instant.", "prov.by.circuit": "par circuit", "prov.by.category": "par catégorie", "prov.by.unknown": "",
