  "prov.byCategory": "Liste par catégorie : pas de calcul (la valeur d'un circuit demande tous ses coureurs).",
  "prov.values": "Valeur du circuit :", "prov.place": "Pl.", "prov.name": "Nom", "prov.club": "Club", "prov.cat": "Cat.", "prov.time": "Temps",
  "prov.cols": "{cnSCap} J-15 → score → {cnS}", "prov.colHint": "Calcul provisoire : {cnThe} du coureur 15 jours avant la course, le score de la course, {cnThe} après la course. En dessous, une fois la course publiée, le score et {cnThe} publiés pour la même méthode (ceux de la FFCO pour la méthode officielle), avec l'écart de score en rouge.",
  "prov.pub": "publié :", "prov.catCn": "Catégorie d'après les données CN (sa dernière course), la liste de l'organisateur ne la donne pas", "prov.pubCols": "publié : score → {cnS}",
  "prov.unmatched": "Coureur introuvable au CN (aucune licence rapprochée)",
  "prov.scoreDef": "Scores calculés comme sur le reste du site, à partir des coureurs retrouvés au CN : un coureur introuvable ne compte pas dans la valeur du circuit, ce qui peut l'écarter un peu du calcul final.",
  "spl.title": "Temps intermédiaires",
  "spl.lede": "Les temps intermédiaires publiés par les organisateurs, circuit par circuit : le tableau des temps et du temps perdu, les écarts, les passages, les inter-postes piégeux, le profil, le face-à-face, les groupes, l'autonomie (qui a suivi qui), la régularité, et un bilan par coureur.",
  "spl.none": "Aucun temps intermédiaire trouvé pour l'instant.", "spl.finish": "Arrivée",
  "ra.lede": "Les courses récentes dont les temps intermédiaires sont publiés, et celles en direct qui en donnent : choisissez-en une pour analyser ses temps circuit par circuit — temps perdu, écarts, passages, inter-postes, groupes, régularité.",
  "ra.mine": "Mes courses seulement",
  "ra.mine.tag": "ma course",
  "ra.mine.tip": "Vous êtes reconnu dans les résultats de cette course",
  "ra.relay.tag": "relais",
  "ra.relay.tip": "Un relais : chaque relayeur de chaque catégorie est un circuit ; aux postes d'une fourche (« 127/172 »), les temps sont comparés par position",
  "ra.def": "Une course figure ici pendant 60 jours dès qu'un de ses circuits a des temps intermédiaires publiés par l'organisateur (WinSplits, Helga, liveresultat, son site ou son dépôt). La colonne « Résultats » mène à la page de la course.",
  "ra.empty": "Aucune course avec temps intermédiaires dans les 60 derniers jours.",
