  "os.help.csv": "CSV :",
  "os.help.csv.text": "une ligne d'en-tête, puis un coureur par ligne. Colonnes reconnues, dans n'importe quel ordre : Heure (ou Départ), Nom, Prénom (ou Nom prénom en une colonne), Club, Circuit, Catégorie. L'heure et le nom suffisent ; sans colonne Circuit, la liste est rangée par catégorie. Séparateur point-virgule, virgule ou tabulation. Exemple :",
  "os.help.csv.example": "Circuit;Heure;Nom;Prénom;Club;Catégorie\nViolet long;10:00;DUPONT;Jeanne;0109;D21\nViolet long;10:02;MARTIN;Paul;7707;H35\nOrange;10:01;LEROY;Léa;0111;D16",
  "os.help.csv.notes": "Heures en 10:02 ou 10h02 (ou 10:02:30). Club : son numéro, éventuellement suivi de son nom, aide à reconnaître les coureurs. Les exports CSV d'OE et de MeOS sont lus aussi.",
  "os.help.sheet": "Google Sheets :",
  "os.help.sheet.text": "collez le lien de la feuille, partagée à « Tous les utilisateurs qui ont le lien ». Elle peut suivre la disposition CSV ci-dessus, ou une grille : une ligne avec le nom des circuits, puis un en-tête Heure / Nom prénom / Club répété pour chaque circuit, un départ par ligne :",
  "os.help.sheet.example": "         Violet long          Orange\nHeure    Nom prénom    Club   Nom prénom   Club\n10:00    Jeanne DUPONT 0109   Léa LEROY    0111\n10:02    Paul MARTIN   7707\nUne colonne Heure par circuit convient aussi.",
