  "ad.m.pending": "{n} en attente de confirmation", "ad.m.disabled": "désactivés : {n}", "ad.m.share": "{p} % des inscrits", "ad.m.since": "inscrits depuis le {d}",
  "ad.m.partial": "Les visites sont comptées depuis le {d} : jusqu'au {full}, la fenêtre de {n} jours n'est pas encore complète et les actifs sont sous-estimés. Inscrit : compte confirmé, non désactivé. Un compte supprimé disparaît de l'historique.",
  "ad.m.def": "Actif : au moins une page vue dans les {n} derniers jours (heure de Paris). Inscrit : compte confirmé, non désactivé. Un compte supprimé disparaît de l'historique.",
  "ad.st.lede": "Les sites d'organisateurs à contacter : ceux dont le robots.txt interdit les robots (la collecte les lit quand même, quelques requêtes par course) et ceux qui bloquent activement les robots (jamais contournés : leurs résultats ne sont pas lus). Pour chacun, les courses concernées.",
  "ad.st.none": "Aucun site pour l'instant : la liste se remplit à chaque passage de la collecte.",
