  // beta notices (beta.js, app.js menus)
  "beta.mark": "bêta",
  "beta.mark.tip": "Version bêta : encore peu testée",
  "beta.tag": "Bêta",
  "beta.try.m": "essayez-le librement, et dites-nous ce que vous en pensez — chaque remarque et chaque bug signalé nous aident à l'améliorer.",
  "beta.try.f": "essayez-la librement, et dites-nous ce que vous en pensez — chaque remarque et chaque bug signalé nous aident à l'améliorer.",
  "beta.tracer.title": "Le tracé, en version bêta",
  "beta.tracer.subject": "Tracé : ",
  "beta.tracer.body": "<p>Le tracé vient d'être réalisé et n'a encore été que peu testé. C'est une <b>version bêta</b> : {try}</p><p>Pour l'instant, nous ne le conseillons pas encore pour préparer une vraie compétition, mais nous espérons qu'il le sera bientôt. En attendant, il convient très bien aux <b>cartes d'entraînement</b>.</p>",
  "beta.tracer.note": "Version bêta, encore peu testée : idéale pour les cartes d'entraînement, pas encore conseillée pour une compétition.",
  "beta.multi.title": "Comparer avec les autres coureurs, en version bêta",
  "beta.multi.subject": "Analyse : ",
  "beta.multi.body": "<p>« Comparer avec les autres coureurs » et les analyses des organisateurs viennent d'être réalisés et n'ont encore été que peu testés. C'est une <b>version bêta</b> : {try}</p><p>Il peut encore y rester des erreurs : une carte mal calée, une trace décalée, un passage à un poste mal daté, un temps d'interposte faux. Vérifiez ce qui vous étonne, et signalez-le-nous.</p>",
  "beta.multi.note": "Version bêta, encore peu testée : il peut rester des erreurs dans les cartes calées, les traces et les temps.",
  "beta.multi.tip": "Version bêta, encore peu testée : signalez les problèmes par « Nous écrire » (le menu de votre nom)",
  "beta.direct.title": "Diffuser en direct, en version bêta",
  "beta.direct.subject": "Diffuser en direct : ",
  "beta.direct.body": "<p>« Diffuser en direct » vient d'être réalisé et n'a encore été que peu testé. C'est une <b>version bêta</b> : {try}</p><p>Pour l'instant, ne comptez pas sur lui seul pour le direct d'une compétition : gardez votre solution habituelle (liveresultat, l'affichage à l'aréna). Essayez-le d'abord à un entraînement, ou à côté de votre direct habituel.</p>",
  "beta.direct.note": "Version bêta, encore peu testée : essayez-la à un entraînement ou à côté de votre direct habituel ; ne comptez pas encore sur elle seule pour une compétition.",
  "beta.results.subject": "Résultats (Orga) : ",
  "beta.results.note": "Version bêta, encore peu testée : vérifiez sur « Résultats » ce que votre dépôt y montre, et signalez-nous ce qui ne va pas.",
  "beta.starts.subject": "Horaires (Orga) : ",
  "beta.starts.note": "Version bêta, encore peu testée : vérifiez la liste de départ publiée et l'export avant de vous en servir le jour de la course.",
