  // IA (pages/ask.js)
  "ia.ex.1": "Quels coureurs de mon club sont dans le meilleur centile de leur catégorie en forêt ? Fais un tableau.",
  "ia.ex.2": "Trace l'écart entre mon CN officiel et mon indice Ozimut sur les 3 dernières années.",
