  "ia.data": "Les données",
  "ia.lede": "Posez une question sur les classements, les résultats, les clubs : une IA écrit la requête, votre navigateur l'exécute sur les données du site et en fait un tableau ou un graphique.",
  "ia.placeholder": "Par exemple : mon indice Ozimut en forêt mois par mois depuis 2024",
