  "ia.ask": "Demander",
  "ia.note": "Gratuit, dans la limite d'une centaine de questions par jour pour tout le site (15 par personne et par jour ; sans limite avec votre propre clé, ci-dessous). L'IA ne voit pas les données : elle écrit une requête, que votre navigateur exécute. Elle peut se tromper : l'interprétation retenue et la requête sont affichées sous chaque réponse.",
  "ia.byok.summary": "Votre propre clé d'API : Claude, ChatGPT, Gemini ou OpenRouter",
  "ia.byok.intro": "Un modèle plus puissant, à vos frais : votre navigateur l'appelle directement avec votre clé.",
