  "ia.byok.forget": "Oublier la clé",
  "ia.byok.privacy": "La clé reste dans ce navigateur : elle n'est jamais envoyée à Ozimut (sans « Se souvenir », elle s'efface à la fermeture de l'onglet ; elle s'efface aussi à la déconnexion). Le fournisseur reçoit la question, la description des tables et votre numéro de licence — jamais les données —, selon ses conditions, et vous facture à ses tarifs (une question coûte de moins d'un centime à environ un centime). Créez une clé réservée à cet usage, avec une limite de dépenses : un script de la page pourrait la lire.",
