  // « Relais nationaux » (pages/relayhistory.js; 2026-10-26)
  "nav.relayHistory": "Palmarès",
  "rh.title": "Palmarès",
  "rh.lede": "Les palmarès des relais nationaux — le Championnat de France des Clubs (CFC) depuis 1999 et le Critérium National des Équipes (CNE) depuis 2006, le Championnat de France de Relais Sprint depuis 2017 — et des championnats de France individuels, à pied, à VTT et à ski : moyenne distance, longue distance, sprint et, à pied, nuit.",
  "rh.none": "L'historique des relais n'est pas disponible.",
  "rh.sources": "Classements rassemblés dans les archives : LIFCO, l'ancien site de la FFCO (archives.ffcorientation.fr), l'ancien site du CO Mulhouse, la lettre du NOSE « ECO NOSE n°19 », les fichiers des organisateurs et O'Live. CFC 1999-2003 : le seul vainqueur connu ; 2004-2005 : extraits ; CNE 2015 : quelques places ; 2019 : un extrait. Une erreur, un fichier manquant ? Écrivez-nous.",
  "rh.compShort.cfc": "CFC",
  "rh.compShort.cne": "CNE",
  "rh.lowerDiv": "L'ordre du fichier de résultats : le podium officiel de la FFCO peut en écarter l'équipe d'un club qui en a une en division supérieure.",
  "rh.tab.champ": "Champions",
  "rh.tab.ceds": "Éditions championnats",
  "rh.tab.crank": "Classements championnats",
  "ch.sources": "Championnats individuels : les résultats publiés par la fédération depuis 2011 ; de 2001 à 2010, ceux qu'ont gardés l'ancien site de la fédération (archivé par la Wayback Machine), les clubs, les ligues et WinSplits, parfois partiels (seuls les premiers et quelques coureurs d'un club) ou réduits aux vainqueurs (2001). Avant 2008 les catégories étaient des tranches d'âge : Senior (21) de 21 à 39 ans, Vétéran 1 à 4 (40, 50, 60, 70) de dix ans. Les titres vont aux coureurs français ; les étrangers sont classés hors championnat. Rien n'est en ligne avant 2001.",
