  "nav.descriptions": "Définitions de postes", "cd.title": "Définitions de postes",
  "cd.lede": "Les symboles des définitions de postes de l'IOF, colonne par colonne, avec leur numéro, leur nom et leur description tels que la spécification les donne et, pour l'objet du poste, les symboles de carte qu'elle lui fait correspondre.",
  "cd.lang": "Noms aussi en…", "cd.lang.none": "—",
  "cd.lang.tip": "Affiche sous chaque nom celui qu'imprime une feuille de définitions dans une autre langue (23 langues) : utile pour une course à l'étranger aux définitions en texte. La page reste dans la langue du site.",
  "cd.search": "Rechercher", "cd.search.ph": "un nom, un mot, un numéro",
  "cd.practice": "S'entraîner", "cd.practice.off": "Non", "cd.practice.names": "Masquer les noms", "cd.practice.map": "Masquer les symboles", "cd.practice.sym": "Masquer les dessins de carte",
  "cd.practice.hint": "Les noms sont masqués : touchez un symbole pour le découvrir, une seconde fois pour le masquer de nouveau.",
  "cd.practice.hint.map": "Seuls les dessins de carte sont montrés : imaginez la définition, puis touchez le dessin pour découvrir le symbole et son nom, une seconde fois pour les masquer de nouveau.",
  "cd.practice.hint.sym": "Seuls les symboles sont montrés : imaginez l'objet tel que la carte le dessine, puis touchez le symbole pour découvrir la carte et le nom, une seconde fois pour les masquer de nouveau.",
  "cd.intro": "Lire une ligne de définitions", "cd.intro.hint": "Chaque poste a sa ligne de huit cases, lue de gauche à droite : chaque colonne répond à une question. Un exemple :",
  "cd.intro.words": "En clair : « {x} »",
  "cd.letter.A": "Le numéro du poste, dans l'ordre du circuit", "cd.letter.B": "Le code du poste, inscrit sur la balise",
  "cd.letter.C": "Lequel, quand plusieurs objets semblables sont dans le cercle", "cd.letter.D": "L'objet du poste",
  "cd.letter.E": "Son aspect, quand il faut le préciser", "cd.letter.F": "Ses dimensions, ou les deux objets qui se croisent ou se rejoignent",
  "cd.letter.G": "Où se trouve la balise par rapport à l'objet", "cd.letter.H": "D'autres informations : secours, ravitaillement, poste contrôlé",
  "cd.source": "Numéros, noms, descriptions et correspondances avec les cartes : spécification internationale des définitions de postes de l'IOF (ISCD 2024) ; le français reprend les termes de la traduction de la FFCO (2018). Dessins des symboles de définition : Purple Pen. Symboles de carte : dessinés par Ozimut d'après ISOM 2017-2 et ISSprOM 2019-2, comme sur la page « Symboles de carte ».",
  "cd.col.C": "Colonne C · Lequel des objets semblables", "cd.col.C.hint": "Quand plusieurs objets semblables se trouvent dans le cercle.",
  "cd.col.D": "Colonne D · L'objet : {f}", "cd.col.D.hint": "L'objet au centre du cercle, tel que la carte le représente. Sous chacun, les symboles de carte que la spécification lui fait correspondre, avec leur numéro : l'objet dessiné avec chacun d'eux dans un cercle de poste, à l'échelle de la carte (cercle de 5 mm en forêt, de 6 mm en sprint).",
  "cd.fam.1": "reliefs", "cd.fam.2": "rochers et pierres", "cd.fam.3": "eau et marais", "cd.fam.4": "végétation", "cd.fam.5": "objets artificiels",
  "cd.fam.6": "objets particuliers",
  "cd.col.E": "Colonne E · Précisions sur l'objet", "cd.col.E.hint": "Son aspect, quand il faut le préciser.",
