  // Coach's analyses, one page each (owner, 2026-10-30)
  "coach.solo.race": "Une compétition", "coach.solo.free": "Un entraînement ou une autre course",
  "coach.multi.race": "Compétitions", "coach.multi.club": "Entraînements",
  "cty.need.guest": "Sans compte, Stats montre le coureur, le classement et les courses sur la période que la fédération publie librement. Créez un compte et rejoignez la France pour tout voir.",
  // the home page in four modules (owner, 2026-10-30)
  "tour.mod.try": "Essayer {mod} sans compte", "tour.mod.orga.cta": "Créer un compte pour organiser",
  "tour.mod.arena.title": "Toute la course, avant, pendant et après",
  "tour.mod.arena.lede": "Arena rassemble chaque compétition au même endroit : l'agenda et ses inscriptions, les horaires de départ dès qu'ils sortent, le direct poste par poste, puis les résultats des organisateurs, souvent le soir même, avec l'analyse complète des temps intermédiaires. Choisissez une course, Arena fait le reste.",
  "tour.mod.stats.title": "Le classement, enfin lisible",
  "tour.mod.stats.lede": "Stats met toute l'orientation en chiffres : votre indice et votre place, le détail exact de chaque calcul, vos progrès saison après saison sur un indice qui se compare d'une année à l'autre depuis 2010, les clubs, les relais et les tendances du pays. Comparez-vous, suivez vos rivaux, comprenez chaque point gagné ou perdu.",
  "tour.mod.coach.title": "Progresser entre deux courses",
  "tour.mod.coach.lede": "Coach transforme vos traces en leçons : rejouez votre course sur votre carte, voyez où filent les secondes, comparez vos choix d'itinéraire à ceux des autres. Révisez les définitions de postes, entraînez votre lecture de carte avec treize jeux et calculez votre VMA.",
  "tour.mod.orga.title": "Organiser, sans s'épuiser",
  "tour.mod.orga.lede": "Orga est une page, vos événements, chacun avec ses outils du jour J et d'après\u00a0: tracer les circuits dans le navigateur, publier horaires et résultats, ouvrir la réservation des horaires, diffuser le direct depuis MeOS, vérifier les temps et offrir aux coureurs leur analyse, avec l'équipe de l'événement. Il s'active à l'inscription ou dans vos réglages, sur ordinateur.",
  "tour.feat.eyebrow": "Tarifs", "tour.feat.title": "Tout est gratuit, module par module",
  "tour.feat.lede": "Chaque ligne ajoute à la précédente. Sans compte, Ozimut montre ce qui est public ; un compte ouvre les alertes et le partage de traces, et le module Orga les outils des organisateurs. Ce qui porte un astérisque demande aussi d'être licencié de la fédération.",
  "tour.feat.note": "Réservé aux licenciés de la fédération : en France, un compte qui a rejoint la France, son numéro de licence FFCO vérifié d'après le nom. Les pays dont tous les résultats sont publics (l'Espagne) s'ouvrent à tous.",
  "tour.feat.star": "Licenciés de la fédération",
  "hub.guest.enter": "Entrer sans compte",
  "home.guest.or": "ou", "home.guest.hint": "Sans compte, de nombreuses fonctions restent réservées aux inscrits : la plupart des fonctions avancées ne sont pas visibles.",
  // the home page's new pictures (2026-10-30)
